    // no 200 may or may not have landed, so there is no claim about it.
    let statuses: Vec<u16> = responses
        .lock()
        .map_err(|_| "responses lock poisoned".to_string())?
        .iter()
        .map(|(status, _)| *status)
        .collect();
    let acked: Vec<&(u64, String)> = entries
        .iter()
        .zip(statuses)
        .filter(|(_, status)| *status == 200)
        .map(|(entry, _)| entry)
        .collect();

    sim.restart();
