/// Mints the operator key (asking twice: the second must be refused), then
/// registers every product and source, all under this run's faults. `None`:
/// faults stopped setup, and the run is given up by name.
fn setup(sim: &mut Sim, kernel: &mut Kernel) -> Result<Option<Keys>, String> {
    let (replies, alive) = run_script(sim, kernel, vec![claim(SECRET), claim(SECRET)])?;
    let Some(operator) = token_of(replies.first()) else {
        sim.give_up("setup: faults kept the operator key from its ack", "");
        return Ok(None);
    };
    let second_operator_key = match replies.get(1) {
        Some((status, _)) => Some(*status),
        None => None,
    };
    if !alive {
        sim.give_up("setup: the kernel stopped under faults", "");
        return Ok(None);
    }
    let mut requests = Vec::new();
    for product in 1..=PRODUCTS {
        requests.push(register_product(product, &operator));
    }
    for source in 1..=SOURCES {
        let request = Request::new(Method::Post, format!("/sources/{source}"));
        requests.push(bearer(request, &operator));
    }
    let (replies, alive) = run_script(sim, kernel, requests)?;
    let products_ok = (0..PRODUCTS as usize).all(|at| matches!(replies.get(at), Some((200, _))));
    let mut sources = BTreeMap::new();
    for source in 1..=SOURCES {
        if let Some(token) = token_of(replies.get((PRODUCTS + source - 1) as usize)) {
            sources.insert(source, token);
        }
    }
    if !alive || !products_ok || sources.len() as u64 != SOURCES {
        sim.give_up("setup: faults kept a registration from its ack", "");
        return Ok(None);
    }
    Ok(Some(Keys {
        operator,
        sources,
        second_operator_key,
    }))
}
